fn contains_consecutive_numbers(a: &Vec<i32>) -> bool {
    // If the array has fewer than two elements, we cannot have a valid adjacent pair.
    if a.len() < 2 {
        return false;
    }

    // Slide a window of size 2 over the slice and check if the second element
    // in any window is exactly one greater than the first.
    a.windows(2).any(|w| w[0] + 1 == w[1])
}

